// Verified dispatcher: recompute the verification root over the canonical
// input and compare it BEFORE running the workload. Drifted input is
// dead-lettered, never executed.
use std::collections::VecDeque;

#[derive(Debug, Clone)]
enum Workload {
    GraphSearch { frontier: Vec<u32> },
    MatrixTile { left: [f32; 4], right: [f32; 4] },
}

// The broker carries an owned envelope, not a borrow into request state.
#[derive(Debug, Clone)]
struct TaskEnvelope {
    task_id: &'static str,
    attempt: u32,
    verification_root: u32,
    workload: Workload,
}

// Route names the workload class so a queue split stays calm later.
fn routing_key(workload: &Workload) -> &'static str {
    match workload {
        Workload::GraphSearch { .. } => "tasks.graph",
        Workload::MatrixTile { .. } => "tasks.matrix",
    }
}

// Recompute the verification root over the canonical input. This is the
// value the dispatcher checks against the envelope before executing.
fn compute_root(workload: &Workload) -> u32 {
    match workload {
        Workload::GraphSearch { frontier } => {
            let mut acc = 17u32;
            for v in frontier {
                acc = acc.wrapping_mul(31).wrapping_add(*v);
            }
            acc
        }
        Workload::MatrixTile { left, right } => {
            let mut acc = 17u32;
            for v in left.iter().chain(right.iter()) {
                acc = acc.wrapping_mul(31).wrapping_add(v.to_bits());
            }
            acc
        }
    }
}

#[derive(Debug)]
enum Outcome {
    Graph(u32),
    Matrix(f32),
    DeadLetter, // verification drift: the workload must not run
}

fn graph_units(frontier: &[u32]) -> u32 {
    frontier.iter().copied().sum()
}

fn matrix_checksum(left: [f32; 4], right: [f32; 4]) -> f32 {
    left.iter().zip(right).map(|(l, r)| *l * r).sum()
}

// The gate sits BEFORE the side effect. Verify, then execute; on drift,
// dead-letter without touching the workload.
fn dispatch(task: &TaskEnvelope) -> Outcome {
    let recomputed = compute_root(&task.workload);
    if recomputed != task.verification_root {
        return Outcome::DeadLetter;
    }
    match &task.workload {
        Workload::GraphSearch { frontier } => Outcome::Graph(graph_units(frontier)),
        Workload::MatrixTile { left, right } => Outcome::Matrix(matrix_checksum(*left, *right)),
    }
}

fn main() {
    let graph = Workload::GraphSearch {
        frontier: vec![2u32, 3, 5],
    };
    let matrix = Workload::MatrixTile {
        left: [1.0f32, 2.0, 3.0, 4.0],
        right: [2.0f32, 3.0, 4.0, 5.0],
    };

    let graph_root = compute_root(&graph);
    let matrix_root = compute_root(&matrix);

    // Three owned envelopes. The last one's root was tampered with in
    // transit, so the dispatcher must refuse to execute it.
    let mut queue: VecDeque<TaskEnvelope> = VecDeque::from([
        TaskEnvelope {
            task_id: "graph-1",
            attempt: 1,
            verification_root: graph_root,
            workload: graph.clone(),
        },
        TaskEnvelope {
            task_id: "matrix-1",
            attempt: 1,
            verification_root: matrix_root,
            workload: matrix.clone(),
        },
        TaskEnvelope {
            task_id: "matrix-2",
            attempt: 2,
            verification_root: matrix_root.wrapping_add(1), // drift
            workload: matrix.clone(),
        },
    ]);

    let mut completed = 0u32;
    let mut dead_lettered = 0u32;
    let mut graph_total = 0u32;
    let mut matrix_total = 0.0f32;

    while let Some(task) = queue.pop_front() {
        let route = routing_key(&task.workload);
        match dispatch(&task) {
            Outcome::Graph(units) => {
                graph_total += units;
                completed += 1;
                let _ = route;
            }
            Outcome::Matrix(sum) => {
                matrix_total += sum;
                completed += 1;
            }
            Outcome::DeadLetter => {
                dead_lettered += 1;
                eprintln!(
                    "drift: task={} attempt={} route={}",
                    task.task_id, task.attempt, route
                );
            }
        }
    }

    println!("completed = {}", completed);
    println!("dead-lettered = {}", dead_lettered);
    println!("graph units = {}", graph_total);
    println!("matrix checksum = {:.1}", matrix_total);
}
